def gen(rng):
    def fmt(a):
        return str(len(a)) + "\n" + " ".join(map(str, a))
    tests = [fmt([0]), fmt([1]), fmt([2]), fmt([1, 2]), fmt([2, 1]), fmt([0, 0, 0]), fmt([1, 1, 2, 2]), fmt([2, 1, 0, 1, 2]),
             fmt([1, 0, 2, 0, 1, 0, 2]), fmt([1, 2, 1, 2, 1, 2, 1, 2])]
    for n in (2, 3, 4, 5, 6, 7, 8, 9):
        for _ in range(3):
            w = rng.choice([(1, 1, 1), (1, 1, 0), (1, 1, 3), (3, 1, 1), (1, 3, 3)])
            tests.append(fmt(rng.choices([0, 1, 2], weights=w, k=n)))
    # mid-size and large inputs (all longer than 400 characters, so they are not brute-force checked)
    for n in (250, 1000):
        tests.append(fmt([rng.randint(0, 2) for _ in range(n)]))
    N = 2 * 10**5
    tests.append(fmt([rng.randint(0, 2) for _ in range(N)]))
    tests.append(fmt([1, 2] * (N // 2)))
    tests.append(fmt([2] * (N // 2) + [1] * (N // 2)))
    tests.append(fmt(rng.choices([0, 1, 2], weights=[1, 8, 8], k=N)))
    return tests

